const ic=n=>`<svg class="ic" viewBox="0 0 24 24" aria-hidden="true">${P[n]||P.more}</svg>`;
const hydrate=(r=document)=>r.querySelectorAll('[data-i]').forEach(e=>{e.innerHTML=ic(e.dataset.i);e.style.display='inline-flex'});

/* ---------- DATA MODELS (swap for API later) ---------- */
const KES=n=>'KES '+Math.round(n).toLocaleString('en-KE');
const SKILLS={brian:['Lawn care','Garden maintenance','Tree pruning'],mercy:['Lawn care','Garden maintenance'],david:['Landscaping','Tree pruning','Supervision'],john:['Cleanup','Lawn care'],grace:['Irrigation','Landscaping','Equipment'],peter:['Landscaping','Tree pruning','Lawn care'],faith:['Garden design','Garden maintenance'],samuel:['Supervision','Cleanup','Irrigation']};
const reqSkill=j=>{const n=j.name.toLowerCase();return /tree/.test(n)?'Tree pruning':/irrigation/.test(n)?'Irrigation':/clean/.test(n)?'Cleanup':/lawn|hedge/.test(n)?'Lawn care':/landscap|install/.test(n)?'Landscaping':'Garden maintenance'};
const revenue=j=>6000+((j.id*7)%14)*1200;
const costs=j=>{const r=revenue(j);return{labour:r*.32,material:r*.12,transport:r*.06,other:r*.03}};
const load=id=>Math.min(100,JOBS.filter(j=>j.assignee===id&&j.date==='Today'&&!['Approved','Cancelled'].includes(j.status)).length*34);
const dist=(t,j)=>{const loc=TEAM.find(x=>x.id===j.assignee)||t;return Math.round(5+Math.abs(t.lat-(35+(j.id*13)%40))/4+Math.abs(t.lng-(25+(j.id*17)%50))/4)};
const matchPct=(t,j)=>SKILLS[t.id].includes(reqSkill(j))?Math.max(60,100-Math.round(load(t.id)/10)-(t.status==='Offline'?40:0)):15;
