const quoteTotal=q=>{const s=q.labour+q.mat+q.trans;const d=s*q.disc/100;return(s-d)*(1+q.tax/100)};

/* ---------- RISK / ALERT ENGINE ---------- */
function risks(j){const r=[];if(['Completed','Approved','Cancelled'].includes(j.status)&&!j.missingReport)return r;
 if(j.delayMin>0)r.push({why:`Worker delayed ${j.delayMin} min; the customer may be waiting.`,act:'Notify the customer and consider reassigning.',fn:`notifyCustomer(${j.id})`,l:'Notify customer'});
 if(!j.assignee&&j.status==='Unassigned')r.push({why:'No worker assigned and the start time is approaching.',act:'Assign the best-matched worker in Smart Dispatch.',fn:"goTo('dispatch')",l:'Open dispatch'});
 if(j.missingReport)r.push({why:'Job is complete but no completion report was submitted.',act:'Ask the worker to submit proof of work.',fn:`toast('Reminder sent to worker (demo).')`,l:'Remind worker'});
 if(j.status==='Awaiting Review')r.push({why:'Report submitted and waiting for manager approval.',act:'Review and approve to release the invoice.',fn:`openJob(${j.id})`,l:'Review'});
 return r}
function alerts(){const a=[];JOBS.forEach(j=>risks(j).forEach(r=>a.push({c:j.delayMin>0||!j.assignee?'':'amber',t:`${j.name}, ${j.location}`,...r})));
 TEAM.filter(t=>load(t.id)>=100).forEach(t=>a.push({c:'amber',t:`${t.name} is overloaded`,why:`${t.name} has 3+ jobs today (100% capacity).`,act:'Rebalance the schedule to an available worker.',fn:'rebalance()',l:'Rebalance'}));
 D.quotes.filter(q=>['Sent','Viewed'].includes(q.st)).forEach(q=>a.push({c:'yellow',t:`Quote ${q.id} awaiting approval`,why:`${q.cust} has not approved yet (${q.st.toLowerCase()}).`,act:'Follow up with the customer.',fn:`toast('Follow-up drafted (demo).')`,l:'Follow up'}));
 D.inv.filter(i=>i.st==='Overdue').forEach(i=>a.push({c:'amber',t:`Invoice ${i.id} overdue`,why:`${i.cust} owes ${KES(i.amt-i.paid)}.`,act:'Send a payment reminder.',fn:`toast('Reminder queued (demo). M-Pesa not connected.')`,l:'Send reminder'}));
 D.stock.filter(s=>s.q-s.use<s.min).forEach(s=>a.push({c:'',t:`${s.n} stock running low`,why:`Stock will fall below minimum (${s.min}${s.u}) after today's scheduled jobs.`,act:`Reorder from ${s.sup}.`,fn:`toast('Reorder drafted (demo).')`,l:'Reorder'}));
 D.equip.filter(e=>e.next==='Overdue').forEach(e=>a.push({c:'yellow',t:`${e.n} maintenance overdue`,why:`Last serviced ${e.last}.`,act:'Schedule maintenance.',fn:`toast('Maintenance booked (demo).')`,l:'Schedule'}));
 return a}
const alertHTML=a=>`<div class="alert ${a.c}"><div><b>${a.t}</b><p><b>Why:</b> ${a.why}</p><p><b>Recommended:</b> ${a.act}</p></div><button class="btn btn-primary btn-sm" onclick="${a.fn}">${a.l}</button></div>`;
function notifyCustomer(id){const j=JOBS.find(x=>x.id===id),c=customerById(j.customerId);openM(`<h2>Message to ${c.name}</h2><p style="color:var(--muted);font-size:12px">Channels are integration-ready. Nothing is sent until WhatsApp/SMS/Email are connected.</p><div class="field full"><label>Message preview</label><textarea>Hi ${c.name.split(' ')[0]}, ${teamById(j.assignee)?.name.split(' ')[0]||'our team'} is running about ${j.delayMin||10} minutes behind. We apologise and will arrive shortly.</textarea></div><div class="modalactions"><button class="btn btn-primary" onclick="closeModal();toast('Message queued (demo, no provider connected).')">Queue message</button><button class="btn btn-secondary" onclick="closeModal()">Cancel</button></div>`)}
const openM=h=>{document.getElementById('modalbody').innerHTML=h;document.getElementById('modal').classList.add('show')};
function whyRisk(id){const j=JOBS.find(x=>x.id===id),r=risks(j);openM(`<div class="modalhead"><h2>Why is this at risk?</h2><button class="btn btn-ghost btn-sm" onclick="closeModal()" aria-label="Close">×</button></div><p><b>${j.name}</b> · ${j.location}</p>${r.map(x=>`<div class="rec-box"><b>Why:</b> ${x.why}<br><b>Recommended action:</b> ${x.act}<div class="actions"><button class="btn btn-primary btn-sm" onclick="closeModal();${x.fn}">${x.l}</button></div></div>`).join('')||'<p>No active risk.</p>'}`)}

/* ---------- ASSIGN / CAPACITY ---------- */
function assign(jid,tid){const j=JOBS.find(x=>x.id===jid),t=teamById(tid);j.assignee=tid;j.status='Assigned';j.timeline.push({t:nowStr(),e:'Assigned to '+t.name+' by Taskyn dispatch'});addNotification('green','Assigned',`${t.name} assigned to ${j.name}.`,j.id);updateBadges();toast(`${j.name} assigned to ${t.name}.`);render(cur)}
function rebalance(){const over=TEAM.filter(t=>load(t.id)>=100)[0];if(!over)return toast('Schedule is already balanced.');const j=JOBS.find(x=>x.assignee===over.id&&x.date==='Today'&&x.status==='Assigned'||x.assignee===over.id&&x.status==='Accepted');const best=TEAM.filter(t=>t.id!==over.id&&t.status!=='Offline').sort((a,b)=>matchPct(b,j||JOBS[0])-matchPct(a,j||JOBS[0]))[0];if(j){assign(j.id,best.id)}else toast('No movable job found; open jobs are already in progress.')}
const capLabel=(t,p)=>t.status==='Offline'?['Off duty','gray']:p>=100?['Overloaded','red']:p>=60?['Busy','amber']:['Available','green'];
const capHTML=()=>`<div class="panel"><h3>Team capacity</h3><p>Today's workload per worker.</p>${TEAM.map(t=>{const p=load(t.id),[l,c]=capLabel(t,p);return`<div class="caprow"><span>${t.name.split(' ')[0]}</span><div class="capbar"><span style="width:${p}%;background:var(--${c==='gray'?'muted':c==='green'?'green2':c})"></span></div><b>${p}%</b><span class="pill ${c}">${l}</span></div>`}).join('')}<div class="actions"><button class="btn btn-secondary" onclick="rebalance()">${ic('repeat')}Rebalance schedule</button></div></div>`;

