let cur='overview';
window.goTo=function(v){cur=v;const box=document.getElementById('views');let s=document.getElementById(v);
 if(!s){s=document.createElement('section');s.id=v;s.className='view';box.appendChild(s)}
 document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));s.classList.add('active');
 document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.v===v));
 document.querySelectorAll('.mnav button').forEach(x=>x.classList.toggle('active',x.dataset.m===v));
 const t=TT[v]||{issues:['Issues','Everything that needs a decision.'],schedule:['Schedule','Upcoming jobs by day.'],team:['Field team','Skills, capacity and availability.'],customers:['Customers','Profiles and service history.'],reports:['Reports','Operations, revenue and performance.'],analytics:['Analytics','Operations, team, customers and finance.']}[v]||['',''];
 document.getElementById('title').textContent=v==='overview'?'Good morning, Manager':t[0];
 document.getElementById('subtitle').textContent=v==='overview'?new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}):t[1];
 s.innerHTML='<div class="sk"></div><div class="sk"></div>';window.scrollTo(0,0);
 setTimeout(()=>render(v),120)};
const R4={};
const _render=render;
window.render=function(v){const el=document.getElementById(v);try{(R4[v]||(()=>_render(v)))();hydrate(el);if(!R4[v]&&el.innerHTML==='')throw 0}catch(e){el.innerHTML=`<div class="empty"><b>Something went wrong while loading this page.</b><div class="actions" style="justify-content:center"><button class="btn btn-primary" onclick="render('${v}')">Try again</button><button class="btn btn-secondary" onclick="goTo('overview')">Go to Overview</button></div></div>`}};
const empty=(t,b,a)=>`<div class="empty"><b>${t}</b>${b||''}${a?`<div class="actions" style="justify-content:center">${a}</div>`:''}</div>`;
const tbl=(h,rows,em)=>rows.length?`<div class="tablewrap panel" style="padding:0"><table><thead><tr>${h.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:em;
const pl=(t,c)=>`<span class="pill ${c}">${t}</span>`;
const stc={Paid:'green',Approved:'green','Partially Paid':'amber',Overdue:'red',Sent:'blue',Viewed:'blue',Draft:'gray',Rejected:'red',Expired:'gray',New:'blue',Reviewing:'amber',Converted:'green',Good:'green',Fair:'amber','In use':'blue',Available:'green','Maintenance due':'red'};
const sp=t=>pl(t,stc[t]||'gray');
const mini=(t,v,c,fn)=>`<button class="card metric" ${fn?`onclick="${fn}"`:''}><small>${t}</small><strong ${c?`style="color:var(--${c})"`:''}>${v}</strong></button>`;

/* ---------- OVERVIEW / COMMAND CENTRE ---------- */
R4.overview=()=>{const T=JOBS.filter(j=>j.date==='Today'&&j.status!=='Cancelled'),sched=T.filter(j=>j.assignee).length,atr=JOBS.filter(j=>risks(j).length&&j.status!=='Awaiting Review').length,rev=JOBS.filter(j=>j.date==='Today').reduce((a,j)=>a+revenue(j),0),aw=JOBS.filter(j=>j.status==='Awaiting Review').length;
 const cap=Math.round(TEAM.filter(t=>t.status!=='Offline').reduce((a,t)=>a+load(t.id),0)/TEAM.filter(t=>t.status!=='Offline').length),top=[...TEAM].sort((a,b)=>load(b.id)-load(a.id))[0],qa=D.quotes.filter(q=>['Sent','Viewed'].includes(q.st)).length;
 const delayed=JOBS.find(j=>j.delayMin>0);
 document.getElementById('overview').innerHTML=`
 <div class="flow" aria-label="Job lifecycle">${[['Request','requests'],['Quote','quotes'],['Schedule','schedule'],['Dispatch','dispatch'],['Worker','worker'],['Proof','jobs'],['Invoice','invoices'],['Payment','payments'],['Analytics','analytics'],['AI','insights']].map(([l,v])=>`<span onclick="goTo('${v}')">${l.toUpperCase()}</span>`).join('<span style="border:0;cursor:default">→</span>')}</div>
 <h3 class="eyebrow" style="margin:16px 0 8px">Today at a glance <span style="color:var(--muted);text-transform:none">(demo data)</span></h3>
 <div class="cards" style="grid-template-columns:repeat(5,1fr)">${mini('Jobs',T.length,'',"goTo('jobs')")}${mini('Scheduled',sched,'green',"goTo('schedule')")}${mini('At risk',atr,'red',"goTo('insights')")}${mini('Awaiting review',aw,'blue',"goTo('reports')")}${mini('Expected revenue',KES(rev),'',"goTo('profit')")}</div>
 <div class="brief" style="margin-top:14px"><div class="eyebrow" style="color:#8fc7a5">${ic('spark')} Taskyn's briefing</div>
  <p>Your team is operating at ${cap}% capacity today. ${top.name.split(' ')[0]} has the highest workload (${load(top.id)}%). ${atr} job${atr!==1?'s are':' is'} currently at risk. ${qa} customer quote${qa!==1?'s are':' is'} awaiting approval.</p>
  <div class="eyebrow" style="color:#8fc7a5;margin-top:14px">Recommended actions</div>
  ${delayed?`<div class="rec"><span>1. Notify the customer about the delayed ${delayed.location} appointment.</span><span class="actions" style="margin:0"><button class="btn btn-secondary btn-sm" onclick="whyRisk(${delayed.id})">Review</button><button class="btn btn-primary btn-sm" onclick="notifyCustomer(${delayed.id})">Apply</button></span></div>`:''}
  <div class="rec"><span>2. Assign ${JOBS.filter(j=>j.status==='Unassigned'&&j.date==='Today').length} unassigned job(s) with Smart Dispatch.</span><span class="actions" style="margin:0"><button class="btn btn-primary btn-sm" onclick="goTo('dispatch')">Apply</button></span></div>
  <div class="rec"><span>3. Review ${JOBS.filter(j=>j.missingReport||j.status==='Awaiting Review').length} incomplete or pending job reports.</span><span class="actions" style="margin:0"><button class="btn btn-primary btn-sm" onclick="goTo('reports')">Review</button></span></div></div>
 <div class="row2"><div><div class="panel"><h3>Needs attention</h3>${alerts().slice(0,4).map(alertHTML).join('')||empty('All clear','Nothing needs attention right now.')}<div class="actions"><button class="btn btn-secondary btn-sm" onclick="goTo('insights')">All insights</button></div></div></div>
 <div><div class="panel"><h3>Today's schedule</h3>${T.filter(j=>j.assignee).sort((a,b)=>a.time.localeCompare(b.time)).slice(0,5).map(j=>`<div class="event" style="display:block"><b>${j.time} · ${j.name}</b><p>${customerById(j.customerId).location} · ${teamById(j.assignee).name} ${pl(j.status,statusColor(j.status,j.delayMin))}</p><div class="actions" style="margin-top:8px"><button class="btn btn-primary btn-sm" onclick="openJob(${j.id})">Open job</button><button class="btn btn-secondary btn-sm" onclick="toast('Navigation opens in Maps (demo).')">${ic('send')}Navigate</button></div></div>`).join('')||empty('No jobs scheduled.','',`<button class="btn btn-primary" onclick="openCreateJob()">${ic('plus')}Create job</button>`)}</div>${capHTML()}</div></div>`};

/* ---------- JOBS COMMAND CENTRE ---------- */
let jf='Today';
R4.jobs=()=>{const F={Today:j=>j.date==='Today',['At Risk']:j=>risks(j).length>0,Unassigned:j=>j.status==='Unassigned',['In Progress']:j=>['In Progress','On Site'].includes(j.status),['Awaiting Review']:j=>j.status==='Awaiting Review',Completed:j=>['Completed','Approved'].includes(j.status),Overdue:j=>j.delayMin>0};
 const L=JOBS.filter(F[jf]);document.getElementById('jobs').innerHTML=`<div class="toolbar"><div class="chips" role="tablist">${Object.keys(F).map(k=>`<button class="chip ${k===jf?'active':''}" onclick="jf='${k}';render('jobs')">${k}</button>`).join('')}</div><button class="btn btn-primary" onclick="openCreateJob()">${ic('plus')}New job</button></div>
 ${L.length?`<div class="jobcards">${L.map(j=>{const r=risks(j),c=customerById(j.customerId);return`<div class="jobcard"><h3>${j.name}</h3><div class="meta">${c.name} · ${j.location} · ${j.time}</div><div class="progress"><span style="width:${j.progress}%"></span></div><div class="jobfoot"><span class="person"><strong>${teamById(j.assignee)?.name||'Unassigned'}</strong></span>${pl(j.status,statusColor(j.status,j.delayMin))}</div><div style="display:flex;justify-content:space-between;margin-top:10px;font-size:12px"><span>${r.length?pl('At risk','red'):pl('On track','green')}</span><b>${KES(revenue(j))}</b></div><div class="actions"><button class="btn btn-primary btn-sm" onclick="openJob(${j.id})">Open job</button>${r.length?`<button class="btn btn-secondary btn-sm" onclick="whyRisk(${j.id})">Why at risk?</button>`:''}</div></div>`}).join('')}</div>`:empty('No jobs here.','Try another filter or create a job.',`<button class="btn btn-primary" onclick="openCreateJob()">${ic('plus')}Create job</button>`)}`};

/* ---------- SMART DISPATCH ---------- */
R4.dispatch=()=>{const U=JOBS.filter(j=>j.status==='Unassigned');document.getElementById('dispatch').innerHTML=`<div class="row2">${U.map(j=>{const ranked=TEAM.map(t=>({t,m:matchPct(t,j),d:dist(t,j)})).sort((a,b)=>b.m-a.m||a.d-b.d),b=ranked[0];return`<div class="panel"><h3>${j.name}</h3><p>${j.location} · Skill: ${reqSkill(j)} · Est. 2h · Preferred ${j.date} ${j.time}</p><div class="rec-box"><span class="eyebrow">${ic('spark')} Taskyn recommends</span><br><b>${b.t.name}</b> <span class="match good">${b.m}% match</span><ul><li>${b.t.status==='Offline'?'Off duty':'Available'}</li><li>${b.d} minutes away (demo estimate)</li><li>Has required skill: ${reqSkill(j)}</li><li>Workload ${load(b.t.id)}%</li></ul><div class="actions"><button class="btn btn-primary" onclick="assign(${j.id},'${b.t.id}')">Assign</button></div></div>
 <div class="actions"><select id="m${j.id}" aria-label="Assign manually" style="height:38px;border:1px solid var(--line);border-radius:10px;padding:0 8px">${ranked.map(x=>`<option value="${x.t.id}">${x.t.name} · ${x.m>=60?x.m+'% match':'Not recommended'}</option>`).join('')}</select><button class="btn btn-secondary" onclick="assign(${j.id},document.getElementById('m${j.id}').value)">Assign manually</button></div></div>`}).join('')||`<div class="panel">${empty('Everything is assigned','Nice work.')}</div>`}</div>${capHTML()}`};

/* ---------- REQUESTS / QUOTES / INVOICES / PAYMENTS ---------- */
R4.requests=()=>{document.getElementById('requests').innerHTML=tbl(['Customer','Service','Location','Requested','Source','Status',''],D.requests.map(r=>[`<b>${r.cust}</b>`,r.svc,r.loc,r.date,r.src,sp(r.st),r.st==='Converted'?'✓ Job created':`<button class="btn btn-primary btn-sm" onclick="convertReq(${r.id})">Convert to job</button>`]),empty('No requests','New requests will appear here.'))};
function convertReq(id){const r=D.requests.find(x=>x.id===id);let c=CUSTOMERS.find(x=>x.name===r.cust);if(!c){c={id:'c'+(CUSTOMERS.length+1),name:r.cust,phone:'YOUR PHONE NUMBER',email:'YOUR EMAIL',location:r.loc};CUSTOMERS.push(c)}JOBS.push(mkJob({name:r.svc,customerId:c.id,location:r.loc,assignee:null,status:'Unassigned',date:r.date==='Today'?'Today':'Tomorrow',time:'10:00',timeline:[{t:nowStr(),e:'Created from '+r.src+' request'}]}));r.st='Converted';updateBadges();toast('Customer, job and schedule slot created. Assign a worker in Dispatch.');render('requests')}
R4.quotes=()=>{document.getElementById('quotes').innerHTML=`<div class="toolbar"><span></span><button class="btn btn-primary" onclick="openQuote()">${ic('plus')}Create quote</button></div>`+tbl(['Quote','Customer','Service','Total','Status',''],D.quotes.map(q=>[q.id,q.cust,q.svc,KES(quoteTotal(q)),sp(q.st),q.st==='Draft'?`<button class="btn btn-secondary btn-sm" onclick="setQ('${q.id}','Sent')">Send to customer</button>`:q.st==='Approved'?`<button class="btn btn-primary btn-sm" onclick="quoteToJob('${q.id}')">Convert to job</button>`:['Sent','Viewed'].includes(q.st)?`<button class="btn btn-secondary btn-sm" onclick="setQ('${q.id}','Approved')">Mark approved</button>`:''])).replace('</div>','</div>')};
const setQ=(id,s)=>{D.quotes.find(q=>q.id===id).st=s;toast('Quote '+s.toLowerCase()+'.');render('quotes')};
function quoteToJob(id){const q=D.quotes.find(x=>x.id===id);const c=CUSTOMERS.find(x=>x.name===q.cust)||CUSTOMERS[0];JOBS.push(mkJob({name:q.svc,customerId:c.id,location:c.location,assignee:null,status:'Unassigned',date:'Tomorrow',time:'09:00',timeline:[{t:nowStr(),e:'Created from approved quote '+id}]}));q.st='Converted';D.quotes.find(x=>x.id===id).st='Approved';toast('Job created from quote. Assign it in Dispatch.');goTo('dispatch')}
function openQuote(){openM(`<div class="modalhead"><h2>Create quote</h2><button class="btn btn-ghost btn-sm" onclick="closeModal()" aria-label="Close">×</button></div><div class="form"><div class="field"><label for="qc">Customer</label><select id="qc">${CUSTOMERS.map(c=>`<option>${c.name}</option>`).join('')}</select></div><div class="field"><label for="qs">Service</label><select id="qs">${D.services.map(s=>`<option>${s.n}</option>`).join('')}</select></div>${[['ql','Labour'],['qm','Materials'],['qt','Transport'],['qd','Discount %'],['qx','Tax %']].map(([i,l])=>`<div class="field"><label for="${i}">${l}</label><input id="${i}" type="number" min="0" value="${i==='qx'?16:0}" oninput="qcalc()"></div>`).join('')}<div class="field"><label>Total</label><b id="qtot" style="font-size:20px">${KES(0)}</b></div></div><div class="modalactions"><button class="btn btn-primary" onclick="saveQ()">Save draft</button><button class="btn btn-secondary" onclick="closeModal()">Cancel</button></div>`)}
const qv=i=>+document.getElementById(i).value||0;
const qcalc=()=>document.getElementById('qtot').textContent=KES(quoteTotal({labour:qv('ql'),mat:qv('qm'),trans:qv('qt'),disc:qv('qd'),tax:qv('qx')}));
function saveQ(){D.quotes.unshift({id:'Q-'+(105+D.quotes.length),cust:document.getElementById('qc').value,svc:document.getElementById('qs').value,labour:qv('ql'),mat:qv('qm'),trans:qv('qt'),disc:qv('qd'),tax:qv('qx'),st:'Draft'});closeModal();toast('Quote saved as draft.');render('quotes')}
R4.invoices=()=>{const done=JOBS.filter(j=>['Approved','Completed'].includes(j.status)&&!D.inv.some(i=>i.job===j.name)).slice(0,3);document.getElementById('invoices').innerHTML=tbl(['Invoice','Customer','Job','Amount','Status'],D.inv.map(i=>[i.id,i.cust,i.job,KES(i.amt),sp(i.st)]),empty('No outstanding invoices','Every job is billed and paid. Great work.'))+`<div class="panel"><h3>Create invoice from completed job</h3>${done.map(j=>`<div class="event" style="justify-content:space-between;align-items:center;flex-wrap:wrap"><span><b>${j.name}</b><p>${customerById(j.customerId).name} · ${KES(revenue(j))}</p></span><button class="btn btn-primary btn-sm" onclick="mkInv(${j.id})">Create invoice</button></div>`).join('')||'<p>All completed jobs are invoiced.</p>'}</div>`};
function mkInv(id){const j=JOBS.find(x=>x.id===id);D.inv.unshift({id:'INV-'+(2046+D.inv.length),cust:customerById(j.customerId).name,job:j.name,amt:revenue(j),st:'Draft',paid:0});toast('Draft invoice created.');render('invoices')}
R4.payments=()=>{const s=x=>D.inv.filter(x).reduce((a,i)=>a+i.amt-(i.st==='Paid'?0:0),0);document.getElementById('payments').innerHTML=`<div class="cards">${mini('Paid',KES(D.inv.reduce((a,i)=>a+i.paid,0)),'green')}${mini('Pending',KES(D.inv.filter(i=>['Sent','Partially Paid'].includes(i.st)).reduce((a,i)=>a+i.amt-i.paid,0)),'blue')}${mini('Overdue',KES(D.inv.filter(i=>i.st==='Overdue').reduce((a,i)=>a+i.amt,0)),'red')}${mini('Refunded',KES(0))}</div><div style="height:14px"></div>`+tbl(['Invoice','Customer','Paid','Balance','Action'],D.inv.map(i=>[i.id,i.cust,KES(i.paid),KES(i.amt-i.paid),i.amt-i.paid>0?`<button class="btn btn-secondary btn-sm" onclick="toast('M-Pesa is not connected. Integration point: /integrations/mpesa (coming soon).')">Request M-Pesa payment</button>`:'✓ Settled']))};

/* ---------- FIELD: LIVE OPS / INVENTORY / EQUIPMENT / SERVICES / RECURRING ---------- */
const KEY=()=>(window.TASKYN_CONFIG||{}).GOOGLE_MAPS_API_KEY;
const toLL=t=>({lat:-1.2921-(t.lat-50)*.0016,lng:36.8219+(t.lng-50)*.0022});
const stat={'On site':'On site','Active':'En route','Delayed':'Delayed','Busy':'On site','Available':'Available','Offline':'Off duty'};
function pickWorker(id){const t=teamById(id),j=JOBS.find(x=>x.assignee===id&&!['Approved','Cancelled'].includes(x.status));if(j&&document.getElementById('gmframe'))showOnMap(j.location);const nx=JOBS.filter(x=>x.assignee===id&&x!==j&&x.status!=='Approved')[0];document.getElementById('wpanel').innerHTML=`<div class="panel"><h3>${t.name}</h3><p>${stat[t.status]}</p><b>Current job:</b> ${j?j.name+' · '+j.location:'None'}<br><b>ETA:</b> ${j?(j.delayMin?j.delayMin+' min late (demo)':'On time (demo)'):'—'}<br><b>Next job:</b> ${nx?nx.name:'None'}<div class="actions">${j?`<button class="btn btn-primary btn-sm" onclick="openJob(${j.id})">Open job</button>`:''}</div></div>`}
R4.live=()=>{const el=document.getElementById('live');el.innerHTML=`<div class="chips" style="margin-bottom:12px">${TEAM.map(t=>`<button class="chip" onclick="pickWorker('${t.id}')">${{'On site':'🟢','Busy':'🟢','Active':'🔵','Delayed':'🟠'}[t.status]||'⚪'} ${t.name.split(' ')[0]} · ${stat[t.status]}</button>`).join('')}</div><div id="mapbox" class="mapbox" aria-label="Live operations map"><div class="sk" style="height:100%;margin:0"></div></div><div id="wpanel"></div><div id="jobmaps"></div>`;
 const fb=note=>{const m=document.getElementById('mapbox');m.innerHTML=`<div class="map" style="height:100%;border:0">${TEAM.map(t=>`<div class="pin ${{'On site':'on','Busy':'on','Active':'sched','Delayed':'delay'}[t.status]||'issue'}" style="left:${t.lng}%;top:${t.lat}%" tabindex="0" role="button" aria-label="${t.name}" onclick="pickWorker('${t.id}')" onkeydown="if(event.key==='Enter')pickWorker('${t.id}')">${t.avatar}<small>${t.name.split(' ')[0]}</small></div>`).join('')}</div><div class="mapnote">${note}</div>`};
 if(!KEY())return gmEmbed('Nairobi, Kenya',11);
 loadMaps().then(()=>{const m=document.getElementById('mapbox');m.innerHTML='';const map=new google.maps.Map(m,{center:toLL({lat:50,lng:50}),zoom:12,disableDefaultUI:true,zoomControl:true});const col={'On site':'#2f8a5b',Busy:'#2f8a5b',Active:'#416d9d',Delayed:'#b87516'};TEAM.forEach(t=>{const mk=new google.maps.Marker({map,position:toLL(t),title:t.name,label:t.avatar,icon:{path:google.maps.SymbolPath.CIRCLE,scale:14,fillColor:col[t.status]||'#718077',fillOpacity:1,strokeColor:'#fff',strokeWeight:2}});mk.addListener('click',()=>pickWorker(t.id))});JOBS.filter(j=>j.assignee&&j.date==='Today'&&!['Approved'].includes(j.status)).forEach(j=>{const a=teamById(j.assignee);new google.maps.Polyline({map,path:[toLL(a),{lat:toLL(a).lat+.01,lng:toLL(a).lng+.01}],strokeColor:'#1f6b45',strokeOpacity:.5,strokeWeight:2})})}).catch(()=>fb('Google Maps could not load. Showing fallback map.'))};
const gmUrl=(q,z)=>'https://maps.google.com/maps?q='+encodeURIComponent(q)+'&z='+z+'&output=embed';
function gmEmbed(q,z){const m=document.getElementById('mapbox');m.innerHTML=`<iframe id="gmframe" title="Google Map" src="${gmUrl(q,z)}" style="width:100%;height:100%;border:0" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe>`;
 const act=JOBS.filter(j=>j.assignee&&j.date==='Today'&&!['Approved','Cancelled'].includes(j.status));
 document.getElementById('jobmaps').innerHTML=`<div class="panel"><h3>Active jobs on the map</h3><p>Opens the job location in Google Maps. Worker positions are demo data.</p>${act.map(j=>`<div class="event" style="justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px"><span><b>${j.name}</b><p>${j.location} · ${teamById(j.assignee).name}</p></span><span class="actions" style="margin:0"><button class="btn btn-secondary btn-sm" onclick="showOnMap('${j.location}')">${ic('map')}Show on map</button><a class="btn btn-secondary btn-sm" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(j.location+', Nairobi, Kenya')}">${ic('send')}Navigate</a></span></div>`).join('')}</div>`}
function showOnMap(loc){const f=document.getElementById('gmframe');if(f)f.src=gmUrl(loc+', Nairobi, Kenya',14);document.getElementById('mapbox').scrollIntoView({behavior:'smooth',block:'center'})}
let mapsP;function loadMaps(){return mapsP||(mapsP=new Promise((res,rej)=>{const s=document.createElement('script');s.src='https://maps.googleapis.com/maps/api/js?key='+encodeURIComponent(KEY())+'&loading=async';s.async=true;s.onload=res;s.onerror=rej;document.head.appendChild(s)}))}
R4.inventory=()=>{document.getElementById('inventory').innerHTML=D.stock.filter(s=>s.q-s.use<s.min).map(s=>`<div class="alert amber"><div><b>⚠ ${s.n}: stock will fall below minimum after today's scheduled jobs.</b></div></div>`).join('')+tbl(['Material','Quantity','Minimum','Unit cost','Supplier','Last restock'],D.stock.map(s=>[`<b>${s.n}</b>`,s.q+s.u,s.min+s.u,KES(s.cost),s.sup,s.last]))};
R4.equipment=()=>{document.getElementById('equipment').innerHTML=tbl(['Item','Type','Condition','Assigned','Location','Last service','Next maintenance','Status'],D.equip.map(e=>[`<b>${e.n}</b>`,e.k,sp(e.cond),e.who,e.loc,e.last,e.next,sp(e.st)]))};
R4.services=()=>{document.getElementById('services').innerHTML=`<div class="panel"><h3>Business category</h3><p>Taskyn configures service templates, skills and checklists per industry.</p><div class="chips">${D.sectors.map((s,i)=>`<button class="chip ${i===0?'active':''}" onclick="toast('${s} templates will load here (demo: Landscaping active).')">${s}</button>`).join('')}</div></div><div class="row3">${D.services.map(s=>`<div class="panel"><h3>${s.n}</h3><p>${KES(s.price)} · ${s.dur} · ${s.skill}</p><p>Equipment: ${s.eq} · Materials: ${s.mat}</p>${s.check.map(c=>`<div class="check">☑ ${c}</div>`).join('')}</div>`).join('')}</div>`};
R4.recurring=()=>{document.getElementById('recurring').innerHTML=`<div class="toolbar"><span></span><button class="btn btn-primary" onclick="toast('Recurring schedule builder (weekly, biweekly, monthly, custom) coming soon.')">${ic('plus')}New recurring service</button></div>`+tbl(['Service','Customer','Interval','Assigned','Next job'],D.recur.map(r=>[`<b>${r.svc}</b>`,`${r.cust} · ${r.loc}`,r.every,r.who,r.next]))};

/* ---------- PROFIT / INSIGHTS / INBOX ---------- */
R4.profit=()=>{const L=JOBS.filter(j=>['Approved','Completed','Awaiting Review'].includes(j.status));document.getElementById('profit').innerHTML=tbl(['Job','Revenue','Labour','Materials','Transport','Other','Profit','Margin'],L.map(j=>{const c=costs(j),r=revenue(j),p=r-c.labour-c.material-c.transport-c.other;return[`<b>${j.name}</b>`,KES(r),KES(c.labour),KES(c.material),KES(c.transport),KES(c.other),`<b>${KES(p)}</b>`,(p/r*100).toFixed(1)+'%']}),empty('No completed jobs yet'))};
R4.insights=()=>{const a=alerts();document.getElementById('insights').innerHTML=a.map(alertHTML).join('')||empty('All clear','Taskyn found nothing that needs attention.')};
R4.inbox=()=>{const act=NOTIFICATIONS.filter(n=>['red','amber'].includes(n.type)),up=NOTIFICATIONS.filter(n=>!['red','amber'].includes(n.type)),row=n=>`<div class="alert ${n.type==='red'?'':n.type==='amber'?'amber':'yellow'}" style="border-left-color:var(--${n.type==='green'?'green2':n.type})"><div><b>${n.title}</b><p>${n.msg} · ${n.t}</p></div><button class="btn btn-secondary btn-sm" onclick="markRead(${n.id});openJob(${n.jobId})">Open</button></div>`;
 document.getElementById('inbox').innerHTML=`<h3 class="eyebrow">Needs action</h3>${act.map(row).join('')||empty('Nothing needs action')}<h3 class="eyebrow" style="margin-top:18px">Updates</h3>${up.map(row).join('')||empty('No updates')}<div class="actions"><button class="btn btn-secondary btn-sm" onclick="markAllRead();render('inbox')">Mark all read</button></div>`};
window.toggleNotif=()=>goTo('inbox');

/* ---------- TEAM / ANALYTICS additions ---------- */
['team','analytics'].forEach(v=>{const o=window['render'+v[0].toUpperCase()+v.slice(1)];R4[v]=()=>{o();const el=document.getElementById(v);if(v==='team')el.insertAdjacentHTML('afterbegin',capHTML()+`<div class="panel"><h3>Skills</h3>${TEAM.map(t=>`<p><b>${t.name}</b>: ${SKILLS[t.id].join(', ')}</p>`).join('')}</div>`);else el.insertAdjacentHTML('beforeend',`<div class="panel"><h3>How are you performing? <span class="pill gray">Demo benchmarks</span></h3><div class="row2"><div><p>Completion rate</p><b>Your business: 91%</b><div class="bar"><span style="width:91%"></span></div><p>Industry benchmark: 84% (demo)</p></div><div><p>Customer satisfaction</p><b>Your business: 4.7</b><div class="bar"><span style="width:94%"></span></div><p>Industry benchmark: 4.3 (demo)</p></div></div></div>`)}});

/* ---------- ASK / INTELLIGENCE ---------- */
const _ask=askTaskyn;
window.askTaskyn=function(q){if(!q)return;const l=q.toLowerCase();let h='';
 if(/risk/.test(l)){const a=alerts().filter(x=>x.t.includes(',')).slice(0,3);h=a.length?a.map(x=>`<b>${x.t}</b><br>${x.why}<div class="actions"><button class="btn btn-primary btn-sm" onclick="${x.fn}">${x.l}</button></div>`).join('<br>'):'No jobs at risk.'}
 else if(/overload/.test(l)){const o=TEAM.filter(t=>load(t.id)>=100);h=o.length?o.map(t=>`${t.name} is at 100% capacity.`).join('<br>')+`<div class="actions"><button class="btn btn-primary btn-sm" onclick="rebalance()">Rebalance schedule</button></div>`:'Nobody is overloaded.'}
 else if(/paid|unpaid/.test(l)){h=D.inv.filter(i=>i.amt>i.paid&&i.st!=='Draft').map(i=>`${i.cust}: ${KES(i.amt-i.paid)} (${i.st})`).join('<br>')+`<div class="actions"><button class="btn btn-primary btn-sm" onclick="goTo('payments')">Open payments</button></div>`}
 else if(/profit/.test(l)){const t=JOBS.filter(j=>j.status==='Approved').sort((a,b)=>revenue(b)-revenue(a))[0];h=t?`Most profitable (demo data): <b>${t.name}</b>, ${KES(revenue(t)*.47)} profit.`:'No completed jobs.'}
 else if(/assign/.test(l)){const j=JOBS.find(x=>x.status==='Unassigned'),b=TEAM.map(t=>({t,m:matchPct(t,j)})).sort((a,b)=>b.m-a.m)[0];h=`For <b>${j.name}</b> I recommend <b>${b.t.name}</b> (${b.m}% match).<div class="actions"><button class="btn btn-primary btn-sm" onclick="assign(${j.id},'${b.t.id}')">Assign</button></div>`}
 if(!h)return _ask(q);const box=document.getElementById('chatmsgs');box.innerHTML+=`<div class="msg user">${q}</div><div class="msg ai"><span class="tag">TASKYN INTELLIGENCE</span>${h}</div>`;box.scrollTop=box.scrollHeight;document.getElementById('askinput').value='';hydrate(box)};
PROMPTS.push('Which jobs are at risk today?','Who is overloaded?','Which customer hasn\'t paid?','Who should I assign this job to?','Which jobs made the most profit?');

/* ---------- WORKER (mobile-first, offline-aware, proof of work) ---------- */
const W={};let offline=false;
R4.worker=()=>{const j=JOBS.find(x=>x.id===currentWorkerJob)||JOBS.find(x=>x.assignee),c=customerById(j.customerId),st=W[j.id]=W[j.id]||{chk:{},before:0,after:0,mats:[],note:'',sign:false,verified:false},svc=D.services.find(s=>j.name.includes(s.n.split(' ')[0]))||D.services[0],me=teamById(j.assignee),act=['On Site','In Progress'].includes(j.status);
 document.getElementById('worker').innerHTML=`<div class="phone"><div class="worker"><div class="eyebrow">Good morning, ${me.name.split(' ')[0]}</div>
 <div class="actions" style="margin:6px 0 10px"><button class="btn btn-sm ${offline?'btn-danger':'btn-secondary'}" onclick="offline=!offline;render('worker')">${ic('wifi')}${offline?'Offline':'Online'} (toggle demo)</button><span class="pill green" id="sync">${offline?'OFFLINE':'✓ Synced'}</span></div>${offline?'<div class="offline">OFFLINE. Changes will sync when connection returns.</div>':''}
 <select aria-label="Choose job" onchange="currentWorkerJob=+this.value;render('worker')" style="width:100%;height:40px;border:1px solid var(--line);border-radius:10px;margin-bottom:10px">${JOBS.filter(x=>x.assignee&&x.status!=='Cancelled').map(x=>`<option value="${x.id}" ${x.id===j.id?'selected':''}>${x.time} ${x.name}</option>`).join('')}</select>
 <h2>${j.name}</h2><div class="wmeta">${c.name} · ${j.location} · ${j.time}</div>${pl(j.status,statusColor(j.status,j.delayMin))}
 <div class="actions"><button class="btn btn-primary" onclick="toast('Opening navigation (demo).')">${ic('send')}Navigate</button>${j.status==='Assigned'?`<button class="btn btn-secondary" onclick="acceptJob(${j.id})">Accept job</button>`:''}${j.status==='Accepted'?`<button class="btn btn-secondary" onclick="startJob(${j.id})">Start / arrive on site</button>`:''}</div>
 ${act?`<h3 style="margin:18px 0 4px;font-size:13px">Checklist</h3>${svc.check.map(k=>`<label class="chk"><input type="checkbox" ${st.chk[k]?'checked':''} onchange="W[${j.id}].chk['${k}']=this.checked;wsync()">${k}</label>`).join('')}
 <h3 style="margin:16px 0 4px;font-size:13px">Proof of work</h3><div class="actions"><button class="btn btn-secondary btn-sm" onclick="W[${j.id}].before++;wsync();render('worker')">${ic('cam')}Before photo (${st.before})</button><button class="btn btn-secondary btn-sm" onclick="W[${j.id}].after++;wsync();render('worker')">${ic('cam')}After photo (${st.after})</button><button class="btn btn-secondary btn-sm" onclick="W[${j.id}].mats.push('Fertilizer — 2kg');wsync();render('worker')">${ic('plus')}Material (${st.mats.length})</button></div>
 <div class="field" style="margin-top:10px"><label for="wn">Notes</label><textarea id="wn" onchange="W[${j.id}].note=this.value;wsync()">${st.note}</textarea></div>
 <label class="chk"><input type="checkbox" ${st.sign?'checked':''} onchange="W[${j.id}].sign=this.checked">Customer confirmation / signature captured</label>
 <div class="actions"><button class="btn btn-primary" onclick="finishJob(${j.id})">Complete job</button></div>`:''}
 ${['Awaiting Review','Completed','Approved'].includes(j.status)?`<div class="check" style="margin-top:12px">${st.verified||j.report?'JOB VERIFIED ✓':'Job completed'}</div>${j.report?`<div class="aireport"><span class="tag">JOB SUMMARY · ${j.report.status}</span>${j.report.summary}</div>`:''}`:''}</div></div>`};
const wsync=()=>{const s=document.getElementById('sync');if(!s)return;if(offline){s.textContent='Queued offline';return}s.textContent='Syncing...';setTimeout(()=>s.textContent='✓ Synced',700)};
function finishJob(id){const j=JOBS.find(x=>x.id===id),s=W[id],svc=D.services.find(x=>j.name.includes(x.n.split(' ')[0]))||D.services[0],miss=svc.check.filter(k=>!s.chk[k]);if(miss.length)return toast('Complete the checklist first: '+miss[0]+(miss.length>1?' +'+(miss.length-1)+' more':''));if(!s.sign)return toast('Customer confirmation is required.');
 const c=customerById(j.customerId);j.status='Awaiting Review';j.progress=100;s.verified=true;j.missingReport=false;j.report={summary:`${j.name} was completed at the customer's ${c.location} property. ${svc.check.slice(0,3).join(', ')} and cleanup were completed. ${s.mats.length?s.mats.join(', ')+' used. ':''}${s.before+s.after} photos uploaded and customer confirmation was received.`,materials:s.mats.length?s.mats:['None'],confirmed:true,status:'Pending Review'};j.timeline.push({t:nowStr(),e:'Completion report submitted'});addNotification('green','Completed',`${j.name} completed. Report ready for review.`,j.id);updateBadges();toast('Job verified. Summary generated for manager approval.');render('worker')}

/* ---------- CUSTOMER PORTAL ---------- */
R4.portal=()=>{const j=JOBS[0],steps=[['Job accepted',1],['Technician assigned',1],['Technician en route',1],['Work in progress',0],['Completed',0]];document.getElementById('portal').innerHTML=`<div class="phone"><div class="panel"><div class="eyebrow">Good morning, Jane</div><h3 style="margin-top:6px">Upcoming service</h3><p>${j.name}<br>Today · ${j.time}<br>Brian Kamau</p>${steps.map(([s,d],i)=>`<div class="check" style="color:${d?'var(--green)':'var(--muted)'}">${d?'✓':i===3?'●':'○'} ${s}</div>`).join('')}<p style="margin-top:8px"><b>ETA:</b> about 10 minutes (demo)</p><div class="actions"><button class="btn btn-primary" onclick="toast('Quote approved (demo).')">Approve quote</button><button class="btn btn-secondary" onclick="toast('Approve completed work (demo).')">Approve work</button><button class="btn btn-secondary" onclick="toast('Message sent to business (demo).')">Message business</button><button class="btn btn-secondary" onclick="toast('Invoice download (demo).')">Download invoice</button><button class="btn btn-secondary" onclick="toast('Request form coming soon.')">Request service</button></div></div></div>`};

/* ---------- SETTINGS / INTEGRATIONS / HARXEL ---------- */
R4.settings=()=>{const I=[['Google Maps',KEY()?'Connected':'Not connected'],['WhatsApp','Coming soon'],['Email','Not connected'],['SMS','Coming soon'],['Payments','Not connected'],['M-Pesa','Coming soon']];document.getElementById('settings').innerHTML=`<div class="panel"><h3>Integrations</h3>${I.map(([n,s])=>`<div class="event" style="justify-content:space-between;align-items:center"><b>${n}</b>${pl(s,s==='Connected'?'green':s==='Coming soon'?'gray':'amber')}</div>`).join('')}</div><div class="row3">${['Business profile','Users & roles','Notifications','Services','Skills','Locations'].map(n=>`<div class="panel"><h3>${n}</h3><div class="actions"><button class="btn btn-secondary btn-sm" onclick="toast('${n} settings coming soon.')">Manage</button></div></div>`).join('')}</div>`};
const HX={site:'https://harxelco.com',phone:'YOUR PHONE NUMBER',email:'YOUR EMAIL'}; /* site is from your Harxel profile; replace placeholders with real details */
R4.harxel=()=>{document.getElementById('harxel').innerHTML=`<div class="hxpage"><div class="eyebrow" style="color:#8fc7a5">Built by Harxel Agency</div><div style="font-weight:800;letter-spacing:.04em;margin-top:6px">[HARXEL LOGO: drop your supplied logo file here]</div><h2>BUILD THE SYSTEM YOUR BUSINESS NEEDS.</h2><p>Need a system like Taskyn for your business? Harxel Agency builds modern websites, digital systems, automation solutions, CRM platforms and AI-powered business tools for growing businesses.</p><div class="eyebrow" style="color:#8fc7a5;margin-top:22px">What Harxel builds</div><div class="hxgrid">${['Websites','Digital Systems','CRM Platforms','AI Chatbots','Business Automation','Custom Software'].map(x=>`<div>${x}</div>`).join('')}</div><p><b style="color:#fff">Taskyn is an example of what we can build for your business.</b></p><div class="actions"><a class="btn btn-primary" href="${HX.site}" target="_blank" rel="noopener">Book a consultation →</a><a class="btn btn-secondary" style="background:transparent;color:#fff;border-color:#35574a" href="${HX.site}" target="_blank" rel="noopener">Contact Harxel</a></div><p style="font-size:12px;margin-top:16px">Website: ${HX.site} · Phone: ${HX.phone} · Email: ${HX.email}</p></div>`};

/* ---------- COMMAND BAR ---------- */
const ACT=[['Create new job','plus',()=>openCreateJob()],['Create quote','file',()=>{goTo('quotes');openQuote()}],['Create invoice','card',()=>goTo('invoices')],['Find customer','users',()=>goTo('customers')],["View today's schedule",'cal',()=>goTo('schedule')],['Dispatch a worker','send',()=>goTo('dispatch')],['View overdue jobs','alert',()=>{jf='Overdue';goTo('jobs')}],['View analytics','trend',()=>goTo('analytics')],['Ask Taskyn','spark',()=>goTo('ask')],...NAVFLAT.map(n=>['Go to '+n[1],n[2],()=>goTo(n[0])])];
let ps=0,pf=[];const pal=document.getElementById('palette'),pq=document.getElementById('palq');
function paint(){pf=ACT.filter(a=>a[0].toLowerCase().includes(pq.value.toLowerCase())).slice(0,9);ps=Math.min(ps,Math.max(0,pf.length-1));document.getElementById('pallist').innerHTML=pf.map((a,i)=>`<button class="pal-item ${i===ps?'sel':''}" role="option" onclick="runPal(${i})">${ic(a[1])}${a[0]}</button>`).join('')||'<div class="empty">No matches</div>'}
const runPal=i=>{closePalette();pf[i][2]()};
window.openPalette=()=>{pal.classList.add('show');pq.value='';ps=0;paint();pq.focus()};
const closePalette=()=>pal.classList.remove('show');
let pd;pq.addEventListener('input',()=>{clearTimeout(pd);pd=setTimeout(paint,80)});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();pal.classList.contains('show')?closePalette():openPalette()}else if(pal.classList.contains('show')){if(e.key==='Escape')closePalette();if(e.key==='ArrowDown'){ps=Math.min(ps+1,pf.length-1);paint()}if(e.key==='ArrowUp'){ps=Math.max(ps-1,0);paint()}if(e.key==='Enter'&&pf[ps])runPal(ps)}else if(e.key==='Escape')closeModal()});
pal.addEventListener('click',e=>{if(e.target===pal)closePalette()});
document.getElementById('kbd').textContent=/Mac/i.test(navigator.platform)?'⌘ K':'Ctrl K';
hydrate();updateBadges();goTo("overview");
